add("theory_title", "Teorioj pri lernotempo", "Teorije o času učenja", "Teorías sobre el tiempo de aprendizaje")
add("theory_10k_title", "Regulo de 10 000 horoj", "Pravilo 10 000 časov", "Regla de las 10 000 horas")
add("theory_10k_author", "Malcolm Gladwell (laŭ Anders Ericsson)", "Malcolm Gladwell (po Andersu Ericssonu)", "Malcolm Gladwell (a partir de Anders Ericsson)")
add("theory_10k_description", "Por atingi majstrecon oni bezonas ĉirkaŭ 10 000 horojn da intenca ekzercado. Tio koncernas elitan nivelon (muzikistoj, sportistoj, ŝakistoj). Gravas ne nur la kvanto, sed ankaŭ la kvalito. Oni kritikas la regulon pro troa simpligo.", "Da by dostignuti majstorstvo, trěbuje se okolo 10 000 časov naměrnoj praktiky. To dotyczy elitnyh izpolniteljev (muzikanty, sportovci, šahisti). Važna ne samo količina, ale i kačestvo. Pravilo kritizujut za prěuprostjenje.", "Para alcanzar la maestría hacen falta unas 10 000 horas de práctica deliberada. Se aplica a quienes rinden a nivel de élite (músicos, deportistas, ajedrecistas). No cuenta solo la cantidad, sino la calidad. Se critica por simplificar demasiado.")
add("theory_10k_works", "✔️ Precizaj fakoj, profesia kariero\\n✖️ Ne helpas por rapida komenco", "✔️ Točne oblasti, profesijna kariera\\n✖️ Ne pomaga za brzy start", "✔️ Campos de precisión, carrera profesional\\n✖️ No sirve para un comienzo rápido")
add("theory_20_title", "Regulo de 20/21 horoj", "Pravilo 20/21 časov", "Regla de las 20/21 horas")
add("theory_20_author", "Josh Kaufman", "Josh Kaufman", "")
add("theory_20_description", "Sufiĉas 20 horoj da koncentrita lernado por komenci ĝui novan kapablon. Taŭgas por ŝatokupoj aŭ komencanta nivelo (ekzemple ukulelo, bazaj frazoj de lingvo, jogo).", "20 časov sosrědotočenogo učenja dovoljno, da by započeti radovati se novoj umětnosti. Godi se za hobi ili početny urovenj (napriklad ukulele, osnovne frazy jezyka, joga).", "Con 20 horas de aprendizaje concentrado basta para empezar a disfrutar de una habilidad nueva. Sirve para aficiones o un nivel inicial (por ejemplo ukelele, frases básicas de un idioma, yoga).")
add("theory_20_works", "✔️ Rapida komenco, ŝatokupoj\\n✖️ Ne por majstreco", "✔️ Brzy start, hobi\\n✖️ Ne za majstorstvo", "✔️ Comienzo rápido, aficiones\\n✖️ No sirve para la maestría")
add("theory_100_title", "Regulo de 100 horoj", "Pravilo 100 časov", "Regla de las 100 horas")
add("theory_100_author", "Neformala eduka ideo", "Neformalna obrazovatelna ideja", "Idea educativa informal")
add("theory_100_description", "Ĉirkaŭ 100 horoj povas doni solidan kompetenton: baza fotografio, bakado, pentrado, stirado aŭ oftaj iloj kiel Excel.", "Okolo 100 časov može dati tvrdu kompetenciju: osnovna fotografija, pečenje, malovanje, voženje ili česte orudja kak Excel.", "Unas 100 horas pueden dar una competencia sólida: fotografía básica, repostería, pintura, conducción o herramientas habituales como Excel.")
add("theory_100_works", "✔️ Praktikaj kapabloj, ŝanĝo de kariero\\n✖️ Ne faka nivelo", "✔️ Praktične umětnosti, změna kariery\\n✖️ Ne ekspertny urovenj", "✔️ Habilidades prácticas, cambios de carrera\\n✖️ No es un nivel experto")
add("theory_1000_title", "Regulo de 1 000 horoj", "Pravilo 1 000 časov", "Regla de las 1 000 horas")
add("theory_1000_author", "Populara en informadiko, lingvoj kaj sendependa laboro", "Popularno v informatike, jezykah i svobodnoj rabotě", "Popular en informática, idiomas y trabajo autónomo")
add("theory_1000_description", "1 000 horoj da koncentrita trejnado povas fari vin profesiulo: de muzikinstruisto kaj kuiristo ĝis tradukisto kaj jogoinstruisto. Sufiĉas por instrui aŭ enspezi.", "1 000 časov sosrědotočenogo trenovanja može učiniti vas profesionalom: od učitelja muziky i kuhara do prěvoditelja i učitelja jogi. Dovoljno, da by učiti ili zarabjati.", "1 000 horas de entrenamiento concentrado pueden convertirte en profesional: desde profesores de música y cocineros hasta traductores e instructores de yoga. Bastan para enseñar o ingresar dinero.")
add("theory_1000_works", "✔️ Profesia sendependeco\\n✖️ Ne monda elito", "✔️ Profesijna samostojnost\\n✖️ Ne světova elita", "✔️ Independencia profesional\\n✖️ No es la élite mundial")
add("theory_comparison_title", "📈 Komparo", "📈 Porovnanje", "📈 Comparación")
add("theory_comparison_text", "• 20 horoj → Bona komenco (amatoro)\\n• 100 horoj → Solida (progresinta komencanto)\\n• 1 000 horoj → Lerta profesiulo\\n• 10 000 horoj → Majstreco (elito)", "• 20 časov → Dobry start (amator)\\n• 100 časov → Tvrdo (naprědny početnik)\\n• 1 000 časov → Umětny profesional\\n• 10 000 časov → Majstorstvo (elita)", "• 20 horas → Buen comienzo (aficionado)\\n• 100 horas → Sólido (principiante avanzado)\\n• 1 000 horas → Profesional hábil\\n• 10 000 horas → Maestría (élite)")
