add("home_hero_intro", "Spuru koncentritan ekzercadon kaj rigardu, kiel malgrandaj kutimoj sumiĝas.", "Slědite sosrědotočenu praktiku i smotrite, kak male naviky se sbirajut.", "Registra el tiempo de práctica concentrada y observa cómo se suman los hábitos pequeños.")
add("sidebar_overview", "Superrigardo", "Prěgled", "Resumen")
add("splash_presents", "prezentas", "predstavja", "presenta")
add("splash_tagline", "Spuru vian tempon. Lernu pli saĝe. Kresku kun pacienco.", "Slědite svoje vrěme. Učite mudrěje. Rastite s trpělivostju.", "Registra tu tiempo. Aprende con más tino. Crece con paciencia.")
add("splash_reflection_1", "Ĉiu horo de ekzercado estas paŝo al majstreco.", "Vsaky čas praktiky jest korak k majstorstvu.", "Cada hora de práctica es un paso hacia la maestría.")
add("splash_reflection_2", "Kapablo estas la rekompenco de bone uzita tempo.", "Umětnost jest nagrada za dobro upotrěbljeno vrěme.", "La habilidad es la recompensa del tiempo bien empleado.")
add("splash_reflection_3", "Malgrandaj horoj, ripetataj, fariĝas majstreco.", "Male časy, povtorjane, stavajut se majstorstvom.", "Horas pequeñas, repetidas, se vuelven maestría.")
add("splash_reflection_4", "Progreso estas pacienco farita videbla.", "Postup jest trpělivost, ktora stala se vidima.", "El progreso es la paciencia hecha visible.")
add("splash_reflection_5", "Tempo investita en lernadon neniam estas perdita.", "Vrěme vloženo v učenje nikogda ne jest izgubjeno.", "El tiempo invertido en aprender nunca se pierde.")
