add("theory_topic_spacing_title", "Revenu al kapablo, anstataŭ amasigi ĉion kune", "Vračajte se k umětnosti, vměsto da by stiskati vse v jedno", "Vuelve a la habilidad en vez de concentrarlo todo junto")
add("theory_topic_spacing_summary", "Esploro pri disigita ekzercado subtenas dismeti lernadon tra pluraj seancoj, anstataŭ fidi nur je amasa ekzercado. La plej bona interspaco dependas de la materialo kaj de tio, kiom longe vi volas konservi ĝin.", "Izslědovanje razdělenoj praktiky podpiraje razložiti učenje na několik sesij, vměsto da by opirati se samo na stisnjenu praktiku. Najlěpši razstoj zavisi od materiala i od togo, kako dolgo hočete jego držati.", "La investigación sobre la práctica distribuida apoya repartir el aprendizaje en varias sesiones en lugar de fiarse solo de la práctica masiva. El mejor intervalo depende del material y de cuánto tiempo quieres retenerlo.")
add("theory_topic_spacing_takeaway", "Provu reveni al kapablo dum pluraj tagoj kaj observu, kion vi memoras kaj kio bezonas pli da ekzercado.", "Popytajte vratiti se k umětnosti prěz několik dni i smotrite, čto pomnite i čto trěbuje veče praktiky.", "Prueba volver a la habilidad durante varios días y observa qué recuerdas y qué necesita más práctica.")
add("theory_topic_spacing_citation", "Nicholas J. Cepeda, Harold Pashler, Edward Vul, John T. Wixted kaj Doug Rohrer. Distributed Practice in Verbal Recall Tasks: A Review and Quantitative Synthesis. Psychological Bulletin, 2006, 132(3), 354–380.", "Nicholas J. Cepeda, Harold Pashler, Edward Vul, John T. Wixted i Doug Rohrer. Distributed Practice in Verbal Recall Tasks: A Review and Quantitative Synthesis. Psychological Bulletin, 2006, 132(3), 354–380.", "Nicholas J. Cepeda, Harold Pashler, Edward Vul, John T. Wixted y Doug Rohrer. Distributed Practice in Verbal Recall Tasks: A Review and Quantitative Synthesis. Psychological Bulletin, 2006, 132(3), 354–380.")
add("theory_topic_spacing_context", "La metaanalizo trarigardis 317 eksperimentojn en 184 artikoloj, kun 839 taksoj de disigita ekzercado.", "Metaanaliza prěgledala 317 eksperimentov v 184 člankah, s 839 ocěnami razdělenoj praktiky.", "El metaanálisis revisó 317 experimentos en 184 artículos, con 839 evaluaciones de la práctica distribuida.")
add("theory_topic_spacing_limitation", "Ĉi tiuj rezultoj koncernas taskojn de lernado kaj rememoro. Ili ne prezentas unu horaron kiel optimuman por ĉiu fizika, socia, arta aŭ profesia kapablo.", "Ti rezultaty kasajut se zadač učenja i pripomněnja. Oni ne predstavjajut jedin raspored kak optimalny za vsaku fizičnu, socialnu, umětničsku ili profesijnu umětnost.", "Estos resultados se refieren a tareas de aprendizaje y recuerdo. No presentan un calendario como óptimo para toda habilidad física, social, artística o profesional.")
add("theory_topic_habit_title", "Kutimo ne havas universalan limdaton", "Navyk ne imaje univerzalny krajny termin", "Un hábito no tiene una fecha límite universal")
add("theory_topic_habit_summary", "Ripeti agon en sama kunteksto povas fari ĝin pli aŭtomata kun la tempo. Tamen la bezonata tempo diferencas inter homoj kaj kondutoj. Maltrafi unu tagon ne signifas, ke la tuta progreso perdiĝis.", "Povtorjati dějanje v tom samom kontekstu može s vrěmenem učiniti jego bolje avtomatičnym. Odnako potrěbno vrěme razlikuje se medžu ljudami i povedenjami. Propustiti jedin denj ne znači, že ves postup izgubjeny.", "Repetir una acción en el mismo contexto puede volverla más automática con el tiempo. Aun así, el tiempo necesario cambia entre personas y conductas. Perder un día no significa que se haya perdido todo el progreso.")
add("theory_topic_habit_takeaway", "Ligu agadon al situacio, kiun vi renkontas regule, kaj rekomencu sen kulpo, kiam seanco mankas.", "Svęžite dějanje so situacijoju, ktoru srečajete regularno, i vozobnovite bez viny, kogda sesija propadena.", "Une la actividad a una situación que encuentres con regularidad y retómala sin culpa cuando falte una sesión.")
add("theory_topic_habit_citation", "Phillippa Lally, Cornelia H. M. van Jaarsveld, Henry W. W. Potts kaj Jane Wardle. How Are Habits Formed: Modelling Habit Formation in the Real World. European Journal of Social Psychology, 2010, 40, 998–1009.", "Phillippa Lally, Cornelia H. M. van Jaarsveld, Henry W. W. Potts i Jane Wardle. How Are Habits Formed: Modelling Habit Formation in the Real World. European Journal of Social Psychology, 2010, 40, 998–1009.", "Phillippa Lally, Cornelia H. M. van Jaarsveld, Henry W. W. Potts y Jane Wardle. How Are Habits Formed: Modelling Habit Formation in the Real World. European Journal of Social Psychology, 2010, 40, 998–1009.")
add("theory_topic_habit_context", "Naŭdek ses volontuloj elektis konduton de manĝado, trinkado aŭ aktiveco por ripeti en la sama kunteksto dum 12 semajnoj. Okdek du partoprenantoj donis sufiĉajn datumojn por analizo. La modelita tempo por atingi 95% de la taksita asimptota aŭtomateco variis de 18 ĝis 254 tagoj.", "Devetdeset šest dobrovoljcev izbralo povedenje jedenja, pitja ili aktivnosti, da by povtorjati jego v tom samom kontekstu prěz 12 nedělj. Osemdeset dva učestnikov dalo dovoljno danov za analizu. Modelovany čas da by dostignuti 95% ocěny asimptotičnoj avtomatičnosti variral od 18 do 254 dni.", "Noventa y seis voluntarios eligieron una conducta de comida, bebida o actividad para repetirla en el mismo contexto durante 12 semanas. Ochenta y dos participantes aportaron datos suficientes para el análisis. El tiempo modelado para llegar al 95% de la automaticidad asintótica estimada varió de 18 a 254 días.")
add("theory_topic_habit_limitation", "Tio estis studo pri formado de kutimoj, ne pri tio, kiom da horoj necesas por majstri kapablon. Ĝi ne subtenas sojlon de majstreco je 21 horoj nek universalan regulon de kutimo je 21 tagoj.", "To bylo izslědovanje o tvorjenju navykov, a ne o tom, koliko časov trěbuje se da by ovladniti umětnost. Ono ne podpiraje prag majstorstva na 21 časov ni univerzalno pravilo navyka na 21 dni.", "Fue un estudio sobre la formación de hábitos, no sobre cuántas horas hacen falta para dominar una habilidad. No respalda un umbral de maestría a las 21 horas ni una regla universal del hábito a los 21 días.")
add("theory_milestones_title", "Mejloŝtonoj de progreso", "Milniky postupa", "Hitos de progreso")
add("theory_milestones_note", "La markoj de 21, 100, 1 000 kaj 10 000 horoj en Time4Skill registras tempon, kiun vi pasigis. Ili estas mejloŝtonoj de progreso, ne science validigitaj stadioj, kaj ili ne antaŭdiras, kiam vi fariĝos fakulo.", "Oznaky 21, 100, 1 000 i 10 000 časov v Time4Skill zapisujut vrěme, koje ste potrětili. Oni sut milniky postupa, a ne naučno prověrjene etapy, i ne prědviđajut, kogda stanete ekspertom.", "Las marcas de 21, 100, 1 000 y 10 000 horas en Time4Skill registran el tiempo que has dedicado. Son hitos de progreso, no etapas validadas científicamente, y no predicen cuándo serás experto.")
add("theory_milestone_100_title", "100 horoj", "100 časov", "100 horas")
add("theory_milestone_1000_title", "1 000 horoj", "1 000 časov", "1 000 horas")
add("theory_milestone_10000_title", "10 000 horoj", "10 000 časov", "10 000 horas")
add("theory_milestone_note", "Mejloŝtono de progreso, ne universala stadio de fakeco.", "Milnik postupa, a ne univerzalna etapa ekspertnosti.", "Hito de progreso, no una etapa universal de pericia.")
