add("tracker_tool_balance", "Tempa saldo", "Časovy balans", "Saldo de tiempo")
add("time_balance_note", "Ĉi tiu saldo povas kreski aŭ malkreski. Ĝi ne estas progreso de kapablo, kaj uzi ĝin ne malpliigas jam registritajn horojn.", "Taky balans može rasti ili padati. On ne jest postup umětnosti, i jego koristanje ne umenšaje već zapisanyh časov.", "Este saldo puede subir o bajar. No es el progreso de una habilidad, y usarlo no reduce las horas ya registradas.")
add("time_balance_empty_title", "Ankoraŭ neniu tempa saldo", "Ješče nema časovogo balansa", "Todavía no hay saldo de tiempo")
add("time_balance_empty_description", "Aldonu saldon, kiam vi volas konservi tempon kaj poste kalkuli ĝin malsupren.", "Dodajte balans, kogda hočete sohraniti vrěme i pozže odčitovati jego.", "Añade un saldo cuando quieras guardar tiempo y contarlo hacia atrás más tarde.")
add("time_balance_add_quarter", "Aldoni 15 min", "Dodati 15 min", "Añadir 15 min")
